const EMPTY_DB={projects:[],clients:[],pricing:[],leads:[]};
let db=load(),view='overview',editing=null,toastTimer,viewHistory=[],finderShowAll=false,recentFilterType='all',recentShowAll=false;let persistedDbSnapshot=JSON.stringify(db),filterStateByView={},renderedView='overview';
let marketSignalsState={items:[],updatedAt:'',loading:false,error:'',loaded:false};
const marketFeedUrl=()=>String(window.BPO_MARKET_FEED_URL||'').trim();
function marketSignalsPanel(){const state=marketSignalsState;const stamp=state.updatedAt?new Date(state.updatedAt).toLocaleString('vi-VN',{dateStyle:'medium',timeStyle:'short'}):'Chưa có lần đồng bộ';return `<section class="panel market-live-panel"><div class="panel-head"><div><h3>Tín hiệu thị trường mới nhất</h3><p>Tự tổng hợp tin công khai về BPO, thuê ngoài, tuyển dụng và lao động tại Việt Nam.</p></div><button class="secondary-btn" type="button" data-refresh-market-signals ${state.loading?'disabled':''}>${state.loading?'Đang cập nhật…':'↻ Cập nhật ngay'}</button></div><div class="market-live-meta"><span>${state.loading?'Đang lấy nguồn công khai…':`Cập nhật dữ liệu: ${esc(stamp)}`}</span><span>${state.items.length} tin · nguồn RSS công khai</span></div>${state.error?`<div class="callout">Chưa tải được dữ liệu mới: ${esc(state.error)}. Dữ liệu hiển thị bên dưới (nếu có) là lần đồng bộ trước.</div>`:''}${state.items.length?`<div class="market-signal-list">${state.items.slice(0,10).map(item=>`<article class="market-signal-item"><div class="market-signal-copy"><a href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">${esc(item.title||'Tin thị trường')}</a><p>${esc(item.source||'Nguồn công khai')} · ${esc(item.published||'Không rõ ngày đăng')}${item.topic?` · ${esc(item.topic)}`:''}</p></div><a class="market-signal-open" href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer" aria-label="Mở nguồn">↗</a></article>`).join('')}</div>`:`<div class="empty-hint">${state.loading?'Đang tải tín hiệu thị trường…':'Chưa có dữ liệu tin mới. Workflow hằng ngày sẽ thu thập các bài viết khi được bật trên GitHub.'}</div>`}<p class="market-source">Tin được lấy từ tiêu đề, nguồn và ngày đăng trong RSS của Google News; app không tự suy đoán doanh nghiệp, giá dịch vụ hoặc xác minh nội dung bài viết. Hãy mở nguồn gốc để kiểm tra trước khi dùng làm quyết định kinh doanh.</p></section>`}
async function refreshMarketSignals(force=false){if(marketSignalsState.loading)return;marketSignalsState.loading=true;marketSignalsState.error='';if($('#marketLivePanel')||view==='overview')render();const candidates=[];const remote=marketFeedUrl();if(remote)candidates.push(remote);candidates.push('data/market-signals.json');let lastError='Không tìm thấy nguồn dữ liệu.';for(const url of [...new Set(candidates)]){try{const response=await fetch(url+(url.includes('?')?'&':'?')+'t='+Date.now(),{cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();if(!data||!Array.isArray(data.items))throw new Error('Sai định dạng dữ liệu');marketSignalsState={items:data.items,updatedAt:data.updatedAt||'',loading:false,error:'',loaded:true};if(view==='overview')render();return}catch(err){lastError=err.message||String(err)}}marketSignalsState.loading=false;marketSignalsState.loaded=true;marketSignalsState.error=lastError;if(view==='overview')render()}

function isBuiltInSampleRecord(record,key){const id=String(record?.id||'');if(/^P-DEMO-0[12]$/.test(id)||/^C-DEMO-0[12]$/.test(id)||/^L-DEMO-01$/.test(id)||/^R-PUBLIC-(0[1-9]|1[0-2])$/.test(id))return true;return false}
function load(){
  try{
    const v=JSON.parse(localStorage.getItem(STORAGE));
    if(v&&Array.isArray(v.projects)&&Array.isArray(v.clients)&&Array.isArray(v.pricing)&&Array.isArray(v.leads)){
      let removed=false;
      for(const key of ['projects','clients','pricing','leads']){const before=v[key].length;v[key]=v[key].filter(record=>!isBuiltInSampleRecord(record,key));if(v[key].length!==before)removed=true;}
      if(removed)localStorage.setItem(STORAGE,JSON.stringify(v));
      return v;
    }
  }catch(e){}
  const empty={projects:[],clients:[],pricing:[],leads:[]};
  try{localStorage.setItem(STORAGE,JSON.stringify(empty))}catch(e){}
  return empty;
}
function save(){try{const serialized=JSON.stringify(db);localStorage.setItem(STORAGE,serialized);persistedDbSnapshot=serialized;return true}catch(e){try{db=JSON.parse(persistedDbSnapshot)}catch{}showToast('Không lưu được dữ liệu trên thiết bị. Bộ nhớ có thể đã đầy; hãy xuất sao lưu và thử lại.');return false}}
const fmt=n=>n==null||n===''?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:2})+' ₫';
function parseDecimal(v){const raw=String(v??'').trim().replace(/\s/g,'');if(!raw)return '';let s=raw;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:''}
function moneyUnit(value,unit){if(value==null||value==='')return 'Chưa cập nhật';const u=unit||'Theo tháng (VNĐ/tháng)';return u.startsWith('%')?`${Number(value).toLocaleString('vi-VN',{maximumFractionDigits:2})}% lương tháng`:fmt(value)+' · '+u}
function formatAmount(value,unit){if(value==null||value==='')return '—';return String(unit||'').startsWith('%')?Number(value).toLocaleString('vi-VN',{maximumFractionDigits:2})+'%':fmt(value)}
const num=n=>Number(n||0).toLocaleString('vi-VN');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allRegions=()=>[...new Set([...db.projects.map(x=>x.region),...db.clients.map(x=>x.region),...db.pricing.map(x=>x.region),...db.leads.map(x=>x.region)].filter(Boolean))].sort();
const statusPill=s=>{let c='';if(/đang chạy|đang hợp tác|đã chuyển đổi/i.test(s||''))c='';else if(/xác minh|đang tiếp cận|đang đàm phán|cần nghiên cứu/i.test(s||''))c='amber';else if(/tạm dừng|mất/i.test(s||''))c='red';else c='gray';return `<span class="pill ${c}">${esc(s||'Chưa cập nhật')}</span>`};
const regionFilter=(id='regionFilter')=>`<select class="control" id="${id}"><option value="">Tất cả khu vực</option>${allRegions().map(r=>`<option>${esc(r)}</option>`).join('')}</select>`;
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function setView(v){if(!v||!({overview:1,projects:1,statistics:1,clients:1,pricing:1,opportunities:1,research:1,data:1,settings:1})[v])return;if(typeof closeSearchOverlay==='function')closeSearchOverlay(false);if(v!==view){viewHistory.push(view);window.scrollTo?.(0,0)}view=v;$$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(typeof closeMenu==='function')closeMenu();else $('#sidebar').classList.remove('open');const titles={overview:'Tổng quan thị trường',projects:'Dự án & nhân sự',statistics:'Thống kê khu vực',clients:'Hồ sơ khách hàng',pricing:'Lương & phí dịch vụ',opportunities:'Cơ hội tiềm năng',research:'Nghiên cứu thị trường',data:'Excel & dữ liệu',settings:'Cài đặt'};$('#pageTitle').textContent=titles[v];$('#crumb').textContent=v==='overview'?'BPO INTELLIGENCE HUB':'BPO INTELLIGENCE HUB / '+titles[v].toUpperCase();const pb=$('#pageBackBtn');if(pb)pb.hidden=v==='overview';const tb=$('.topbar');if(tb)tb.classList.toggle('has-page-back',v!=='overview');render()}
function render(){const scrollY=window.scrollY||0;const filterIds=['regionFilter','districtFilter','wardFilter','statusFilter','industryFilter','typeFilter','clientStatusFilter','verifiedFilter','pricingIndustryFilter','leadStatusFilter','leadIndustryFilter'];if(renderedView===view)filterStateByView[view]=Object.fromEntries(filterIds.map(id=>[id,$('#'+id)?.value]).filter(([,v])=>v!==undefined));const filterState=filterStateByView[view]||{};const q=($('#globalSearch').value||'').trim().toLowerCase();const c=$('#content');if(view==='overview')c.innerHTML=overview(q);else if(view==='projects')c.innerHTML=projectsPage(q);else if(view==='statistics')c.innerHTML=statisticsPage();else if(view==='clients')c.innerHTML=clientsPage(q);else if(view==='pricing')c.innerHTML=pricingPage(q);else if(view==='research')c.innerHTML=researchPage();else if(view==='settings')c.innerHTML=settingsPage();else if(view==='data')c.innerHTML=dataPage();else c.innerHTML=leadsPage(q);for(const [id,value] of Object.entries(filterState)){const el=$('#'+id);if(el&&[...el.options].some(o=>o.value===value))el.value=value}if(['projects','clients','pricing','opportunities'].includes(view))refreshFiltered();filterStateByView[view]=Object.fromEntries(filterIds.map(id=>[id,$('#'+id)?.value]).filter(([,v])=>v!==undefined));renderedView=view;if(view==='data')setupDataPage();if(scrollY>0)requestAnimationFrame(()=>window.scrollTo(0,scrollY));}
function globalSearchResults(q){const query=normFilter(q);if(!query)return '';const records=[];for(const x of db.projects)records.push({type:'project',kind:'Dự án',id:x.id,title:x.customer||x.name||x.id,region:x.region,industry:x.industry,status:x.status,search:x});for(const x of db.clients)records.push({type:'client',kind:'Khách hàng',id:x.id,title:x.name||x.id,region:x.region,industry:x.industry,status:x.status,search:x});for(const x of db.pricing)records.push({type:'pricing',kind:'Benchmark',id:x.id,title:x.position||x.id,region:x.region,industry:x.industry,status:x.verified,search:x});for(const x of db.leads)records.push({type:'lead',kind:'Cơ hội',id:x.id,title:x.name||x.id,region:x.region,industry:x.industry,status:x.status,search:x});const matches=records.filter(x=>normFilter(JSON.stringify(x.search)).includes(query)).slice(0,8);return `<section class="panel global-search-panel"><div class="panel-head"><div><h3>Kết quả tìm kiếm</h3><p>${matches.length?`Hiển thị tối đa 8 hồ sơ phù hợp với “${esc(q)}”.`:`Không tìm thấy hồ sơ phù hợp với “${esc(q)}”.`}</p></div></div>${matches.length?`<div class="global-search-results">${matches.map(x=>`<button type="button" class="global-search-result" data-finder-open="${x.type}" data-id="${esc(x.id)}"><span class="global-search-kind">${esc(x.kind)}</span><span class="global-search-copy"><b>${esc(x.title)}</b><small>${esc([x.region,x.industry].filter(Boolean).join(' · ')||'Chưa có khu vực / ngành')}</small></span><span class="global-search-status">${esc(x.status||'Chưa xác định')}</span></button>`).join('')}</div>`:'<div class="empty-hint">Thử từ khóa khác hoặc kiểm tra dữ liệu đã nhập.</div>'}</section>`}
function refreshGlobalSearchResults(){const out=$('#globalSearchResults');if(out)out.innerHTML=globalSearchResults($('#globalSearch')?.value||'')}
function collectSearchSuggestions(){
 const groups=[
  {label:'Vị trí công việc',values:[...db.projects.flatMap(x=>String(x.positions||'').split(/[\n,;•]+/)),...db.pricing.map(x=>x.position),...db.leads.flatMap(x=>String(x.potential||'').split(/[\n,;•]+/))]},
  {label:'Khu vực',values:[...db.projects.map(x=>x.region),...db.clients.map(x=>x.region),...db.pricing.map(x=>x.region),...db.leads.map(x=>x.region)]},
  {label:'Ngành nghề / lĩnh vực',values:[...db.projects.map(x=>x.industry),...db.clients.map(x=>x.industry),...db.pricing.map(x=>x.industry),...db.leads.map(x=>x.industry)]}
 ];
 return groups.map(g=>({...g,values:[...new Map(g.values.map(v=>String(v||'').trim()).filter(v=>v.length>1).map(v=>[normFilter(v),v])).values()].slice(0,8)}));
}
function renderSearchOverlayContent(q=''){
 const out=$('#searchOverlayContent');if(!out)return;const query=String(q||'').trim();
 if(query){out.innerHTML=globalSearchResults(query)||'<div class="search-empty"><b>Không tìm thấy hồ sơ phù hợp</b><p>Thử từ khóa khác hoặc tìm theo vị trí, khu vực hay ngành nghề.</p></div>';return}
 const groups=collectSearchSuggestions();const total=groups.reduce((n,g)=>n+g.values.length,0);
 out.innerHTML=`<section class="search-suggest-section"><h2>Gợi ý cho bạn</h2><p class="search-suggest-subtitle">${total?'Chọn một từ khóa từ dữ liệu đang lưu trên thiết bị.':'Chưa có từ khóa từ dữ liệu thực tế. Nhập từ khóa sau khi thêm hồ sơ hoặc nhập Excel.'}</p>${groups.map((g,i)=>`<div class="search-suggest-group"><h3><span>${['⌕','⌖','▦'][i]}</span>${esc(g.label)}</h3><div class="search-suggest-chips">${g.values.length?g.values.map(v=>`<button type="button" class="search-suggest-chip" data-search-suggestion="${esc(v)}">${esc(v)}</button>`).join(''):'<span class="search-suggest-none">Chưa có dữ liệu</span>'}</div></div>`).join('')}</section>`;
}
function openSearchOverlay(){const panel=$('#searchOverlay'),input=$('#searchOverlayInput');if(!panel||!input)return;panel.hidden=false;panel.classList.add('visible');panel.setAttribute('aria-hidden','false');document.body.classList.add('search-open');input.value=$('#globalSearch').value||'';renderSearchOverlayContent(input.value);requestAnimationFrame(()=>{input.focus();const n=input.value.length;input.setSelectionRange(n,n)});}
function closeSearchOverlay(restoreFocus=false){const panel=$('#searchOverlay');if(!panel||panel.hidden)return;const input=$('#searchOverlayInput');$('#globalSearch').value=input?.value||$('#globalSearch').value||'';panel.classList.remove('visible');panel.setAttribute('aria-hidden','true');panel.hidden=true;document.body.classList.remove('search-open');if(['projects','clients','pricing','opportunities'].includes(view))refreshFiltered();else if(view==='overview')refreshGlobalSearchResults();if(restoreFocus)$('#globalSearch')?.focus();}

function statisticsPage(){
 const projects=db.projects;
 const active=projects.filter(p=>String(p.status||'').trim()==='Đang chạy');
 const verify=projects.filter(p=>/xác minh|chưa xác minh|cần nghiên cứu/i.test(String(p.status||'')));
 const totalHeadcount=projects.reduce((sum,p)=>sum+Math.max(0,Number(p.headcount)||0),0);
 const activeHeadcount=active.reduce((sum,p)=>sum+Math.max(0,Number(p.headcount)||0),0);
 const marketLeads=db.leads.filter(x=>['Dự án đối thủ','Dự án tiềm năng'].includes(x.recordType));
 const competitorLeads=marketLeads.filter(x=>x.recordType==='Dự án đối thủ');
 const potentialLeads=marketLeads.filter(x=>x.recordType==='Dự án tiềm năng');
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const mapPlaces=[
  {name:'Hà Nội',x:198,y:43,aliases:['ha noi','hanoi']},
  {name:'Bắc Ninh',x:222,y:61,aliases:['bac ninh']},
  {name:'Hải Phòng',x:239,y:77,aliases:['hai phong']},
  {name:'Đà Nẵng',x:244,y:169,aliases:['da nang']},
  {name:'Bình Dương',x:178,y:258,aliases:['binh duong','vsip 1','vsip 2','vsip 3']},
  {name:'Đồng Nai',x:198,y:272,aliases:['dong nai']},
  {name:'TP. Hồ Chí Minh',x:162,y:279,aliases:['hcm','ho chi minh','tp ho chi minh','sai gon','tphcm']},
  {name:'Long An',x:143,y:293,aliases:['long an']}
 ];
 const matchRegion=(region,place)=>{const r=norm(region);return place.aliases.some(a=>r===norm(a)||r.includes(norm(a)))};
 const countFor=(rows,place)=>rows.filter(x=>matchRegion(x.region,place)).length;
 const known=mapPlaces.map(p=>({...p,active:countFor(active,p),verify:countFor(verify,p),market:countFor(marketLeads,p)}));
 const hasMapped=known.some(p=>p.active+p.verify+p.market>0);
 const regionNames=[...new Set([...projects.map(p=>String(p.region||'').trim()),...marketLeads.map(x=>String(x.region||'').trim())].filter(Boolean))];
 const regionCounts=regionNames.map(region=>{const ps=projects.filter(p=>norm(p.region)===norm(region));const ls=marketLeads.filter(x=>norm(x.region)===norm(region));return {region,projects:ps.length,active:ps.filter(p=>String(p.status||'').trim()==='Đang chạy').length,verify:ps.filter(p=>/xác minh|chưa xác minh|cần nghiên cứu/i.test(String(p.status||''))).length,headcount:ps.reduce((sum,p)=>sum+Math.max(0,Number(p.headcount)||0),0),competitors:ls.filter(x=>x.recordType==='Dự án đối thủ').length,potential:ls.filter(x=>x.recordType==='Dự án tiềm năng').length,market:ls.length}}).sort((a,b)=>(b.projects+b.market)-(a.projects+a.market));
 const max=Math.max(1,...regionCounts.map(x=>x.projects+x.market));
 const mapDots=known.filter(p=>p.active+p.verify+p.market>0).map(p=>{const parts=[{key:'active',label:'đang chạy',count:p.active,color:'#159b72',dx:-12},{key:'verify',label:'cần xác minh',count:p.verify,color:'#d94848',dx:0},{key:'market',label:'đối thủ/tiềm năng',count:p.market,color:'#7954c7',dx:12}].filter(x=>x.count>0);return parts.map((x,i)=>`<g class="map-point map-point-${x.key}" transform="translate(${p.x+x.dx},${p.y})"><circle r="10"/><text y="3.2" text-anchor="middle">${x.count>99?'99+':x.count}</text><title>${esc(p.name)} · ${esc(x.label)}: ${x.count} hồ sơ</title></g>`).join('')}).join('');
 const researchUrl=region=>`https://www.google.com/search?q=${encodeURIComponent('dự án BPO tuyển dụng thuê ngoài '+region+' Việt Nam')}`;
 return `<div class="section-head stats-page-head"><div><div class="eyebrow">PROJECT & WORKFORCE ANALYTICS</div><h2>Thống kê dự án & nhân sự</h2><p>Tổng hợp từ dữ liệu dự án và hồ sơ thị trường đã lưu trên thiết bị. Thông tin tìm được trên web cần được người dùng ghi nhận nguồn và xác minh.</p></div><button class="secondary-btn" data-view="projects">Mở danh sách dự án →</button></div>
 <div class="stats-kpi-grid"><article class="stats-kpi"><span class="metric-label">Tổng số dự án nội bộ</span><strong>${num(projects.length)}</strong><small>Hồ sơ dự án đã nhập</small></article><article class="stats-kpi"><span class="metric-label">Dự án đang chạy</span><strong>${num(active.length)}</strong><small><i class="status-dot status-dot-green"></i>${num(verify.length)} dự án cần xác minh</small></article><article class="stats-kpi"><span class="metric-label">Tổng nhân sự ghi nhận</span><strong>${num(totalHeadcount)}</strong><small>Headcount đã nhập trong hồ sơ dự án</small></article><article class="stats-kpi"><span class="metric-label">Đối thủ / dự án tiềm năng</span><strong>${num(marketLeads.length)}</strong><small>${num(competitorLeads.length)} đối thủ · ${num(potentialLeads.length)} dự án tiềm năng</small></article></div>
 <div class="callout stats-map-key"><b>Chú giải bản đồ:</b> <span><i class="status-dot status-dot-green"></i> Đang chạy</span><span><i class="status-dot status-dot-red"></i> Cần xác minh</span><span><i class="status-dot status-dot-purple"></i> Đối thủ / tiềm năng</span></div>
 <div class="stats-content-grid"><section class="panel stats-map-panel"><div class="panel-head"><div><h3>Bản đồ phân bố theo trạng thái</h3><p>Mỗi số trên bản đồ là số hồ sơ khớp địa bàn đã nhận diện.</p></div><span class="map-legend"><i></i> Đang chạy</span></div><div class="vietnam-map-wrap"><svg class="vietnam-map" viewBox="0 0 330 330" role="img" aria-label="Sơ đồ phân bố dự án đang chạy, cần xác minh và dự án đối thủ hoặc tiềm năng"><defs><linearGradient id="landGradient" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--map-land-a)"/><stop offset="1" stop-color="var(--map-land-b)"/></linearGradient></defs><path class="vietnam-land" d="M167 15 L194 25 L214 47 L231 58 L250 73 L242 88 L252 105 L244 122 L252 142 L241 160 L230 176 L235 195 L219 211 L214 232 L198 247 L205 264 L192 281 L174 295 L160 314 L145 307 L149 287 L137 270 L145 250 L131 232 L139 211 L150 193 L157 174 L166 156 L169 136 L163 118 L169 100 L158 82 L164 63 L154 45 Z"/><path class="vietnam-border" d="M167 15 L194 25 L214 47 L231 58 L250 73 L242 88 L252 105 L244 122 L252 142 L241 160 L230 176 L235 195 L219 211 L214 232 L198 247 L205 264 L192 281 L174 295 L160 314 L145 307 L149 287 L137 270 L145 250 L131 232 L139 211 L150 193 L157 174 L166 156 L169 136 L163 118 L169 100 L158 82 L164 63 L154 45 Z"/>${mapDots}</svg><div class="map-callout"><b>${num(projects.length+marketLeads.length)} hồ sơ</b><span>${num(projects.length)} dự án nội bộ · ${num(marketLeads.length)} hồ sơ thị trường</span><small>${hasMapped?'Số liệu được nhóm theo tên khu vực khớp với các điểm minh họa.':'Chưa có hồ sơ nào khớp các điểm minh họa.'} Đây là sơ đồ tham chiếu, không phải bản đồ địa lý theo tỷ lệ. Khu vực chưa khớp vẫn có trong bảng bên cạnh.</small></div></div></section>
 <section class="panel stats-region-panel"><div class="panel-head"><div><h3>Thống kê theo khu vực</h3><p>Dự án nội bộ, nhân sự và hồ sơ đối thủ / tiềm năng.</p></div></div>${regionCounts.length?`<div class="region-list stats-region-list">${regionCounts.map(x=>`<div class="stats-region-item"><div class="stats-region-title"><b>${esc(x.region)}</b><span>${num(x.projects)} dự án</span></div><div class="bar-track"><div class="bar-fill" style="width:${(x.projects+x.market)/max*100}%"></div></div><div class="stats-region-meta"><span><i class="status-dot status-dot-green"></i>${num(x.active)} chạy</span><span><i class="status-dot status-dot-red"></i>${num(x.verify)} xác minh</span><span>${num(x.headcount)} nhân sự</span></div><div class="stats-region-meta"><span>${num(x.competitors)} dự án đối thủ · ${num(x.potential)} tiềm năng</span><a class="source-link" href="${esc(researchUrl(x.region))}" target="_blank" rel="noopener">Tìm nguồn web ↗</a></div></div>`).join('')}</div>`:'<div class="empty-hint">Chưa có dữ liệu dự án hoặc hồ sơ thị trường. Thêm hồ sơ hoặc nhập Excel để xem thống kê.</div>'}<p class="cell-sub stats-disclaimer">Một giá trị khu vực có thể chứa nhiều địa bàn; bảng nhóm theo tên khu vực lưu trong từng hồ sơ.</p></section></div>
 <section class="panel stats-market-panel"><div class="panel-head"><div><h3>Dự án đối thủ & dự án tiềm năng trong khu vực</h3><p>Ghi nhận dự án quan sát được từ nguồn công khai hoặc do người dùng tự nhập. Kết quả web không tự động được nhập vào cơ sở dữ liệu.</p></div><button class="primary-btn" data-add="lead">＋ Thêm hồ sơ thị trường</button></div><div class="toolbar"><select class="control" id="marketRegionFilter"><option value="">Tất cả khu vực</option>${[...new Set(marketLeads.map(x=>x.region).filter(Boolean))].sort().map(r=>`<option>${esc(r)}</option>`).join('')}</select><select class="control" id="marketTypeFilter"><option value="">Đối thủ & tiềm năng</option><option>Dự án đối thủ</option><option>Dự án tiềm năng</option></select><select class="control" id="marketStatusFilter"><option value="">Mọi trạng thái</option><option>Cần xác minh</option><option>Đang tiếp cận</option><option>Đang đàm phán</option><option>Đã chuyển đổi</option><option>Không phù hợp</option><option>Đóng</option></select></div><div id="statsMarketList">${marketLeads.length?`<div class="table-wrap"><table><thead><tr><th>Loại / doanh nghiệp</th><th>Khu vực · Ngành</th><th>Dự án / nhu cầu</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${marketLeads.map(x=>`<tr data-market-row data-region="${esc(x.region||'')}" data-type="${esc(x.recordType||'Cơ hội khách hàng')}" data-status="${esc(x.status||'')}"><td><button type="button" class="record-open" data-lead-detail="${esc(x.id)}"><span class="cell-main">${esc(x.name)}</span><span class="cell-sub">${esc(x.recordType||'Cơ hội khách hàng')}</span></button></td><td>${esc(x.region||'Chưa xác định')}<div class="cell-sub">${esc(x.industry||'')}</div></td><td style="white-space:normal">${esc(x.potential||x.signal||'Chưa mô tả')}</td><td>${x.sourceUrl?`<a class="source-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Mở nguồn ↗</a>`:esc(x.source||'Chưa có nguồn')}<div class="cell-sub">${esc(x.updated||'Chưa cập nhật')}</div></td><td>${statusPill(x.status)}</td><td><button class="small-btn" data-edit="lead" data-id="${esc(x.id)}">Sửa</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-hint">Chưa có hồ sơ đối thủ hoặc dự án tiềm năng. Có thể thêm thủ công hoặc dùng “Tìm nguồn web” ở từng khu vực, sau đó xác minh và lưu hồ sơ.</div>'}</div><p class="cell-sub stats-disclaimer">Nguồn công khai chỉ là tín hiệu nghiên cứu. Chỉ đánh dấu đã xác minh sau khi kiểm tra URL, ngày cập nhật và nội dung nguồn.</p></section>`;
}

function overview(q=''){
const active=db.projects.filter(x=>String(x.status||'').trim()==='Đang chạy');
const needsVerify=db.projects.filter(x=>/xác minh|chưa xác minh|cần nghiên cứu/i.test(String(x.status||'')));
const currentClients=db.clients.filter(x=>x.type==='Khách hàng hiện tại').length;
const prospectClients=db.clients.filter(x=>x.type==='Khách hàng tiềm năng').length;
const roles=new Set(db.projects.flatMap(x=>String(x.positions||'').split(/[,;\n|]+/).map(s=>s.trim()).filter(Boolean))).size;
const leadN=db.leads.filter(x=>!['Đã chuyển đổi','Không phù hợp'].includes(x.status)).length;
const recent=recentActivityItems();
return `
<div class="welcome"><div><div class="eyebrow">BPO SALES COMMAND CENTER</div><h2>Biến dữ liệu thị trường thành cơ hội kinh doanh.</h2><p>Theo dõi dự án, nhân sự, mức lương và phí dịch vụ theo từng khu vực — tất cả trong một nơi.</p></div><button class="primary-btn" data-add="project">＋ Thêm dự án</button></div>
<div id="globalSearchResults">${globalSearchResults(q)}</div><div class="callout dashboard-data-note"><b>Số liệu cập nhật theo dữ liệu đang lưu trên thiết bị.</b> Dữ liệu mới nhập từ Excel sẽ được tính vào tổng khách hàng, dự án và vị trí ngay cả khi trạng thái còn “Cần xác minh”. Chỉ dự án có trạng thái “Đang chạy” mới được tính là đang chạy.</div>
<div class="metric-grid"><div class="metric"><div class="metric-top"><span class="metric-label">Tổng khách hàng</span><span class="metric-icon">▣</span></div><div class="metric-value">${db.clients.length}</div><div class="metric-foot">${currentClients} hiện tại · ${prospectClients} tiềm năng · ${Math.max(0,db.clients.length-currentClients-prospectClients)} nhóm khác</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Tổng dự án</span><span class="metric-icon">▤</span></div><div class="metric-value">${db.projects.length}</div><div class="metric-foot">${active.length} đang chạy · ${needsVerify.length} cần xác minh · tổng nhân sự đang chạy: ${num(active.reduce((a,x)=>a+Number(x.headcount||0),0))}</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Vị trí trong dự án</span><span class="metric-icon">♙</span></div><div class="metric-value">${roles}</div><div class="metric-foot">Số vị trí khác nhau trong toàn bộ danh mục dự án</div></div><div class="metric"><div class="metric-top"><span class="metric-label">Cơ hội đang theo dõi</span><span class="metric-icon">◎</span></div><div class="metric-value">${leadN}</div><div class="metric-foot">Lead chưa chuyển đổi hoặc đóng · ${db.leads.length} tổng cơ hội</div></div></div>
${marketFinder()}
<section class="panel stats-shortcut"><div class="panel-head"><div><h3>Thống kê dự án & nhu cầu nhân sự</h3><p>Xem tổng dự án, nhân sự cần bố trí và phân bố theo khu vực trên bản đồ.</p></div><button class="primary-btn" data-view="statistics">Mở thống kê →</button></div><div class="stats-shortcut-metrics"><span><b>${db.projects.length}</b> dự án đã ghi nhận</span><span><b>${num(db.projects.reduce((sum,p)=>sum+Number(p.headcount||0),0))}</b> nhân sự đã ghi nhận</span></div></section>
<div class="panel"><div class="panel-head"><div><h3>Tín hiệu thị trường từ nguồn công khai</h3><p>Thông tin tham khảo để định hướng survey — không phải báo giá BPO</p></div><button class="text-btn" data-view="research">Nghiên cứu thêm →</button></div><div class="market-stats"><article class="market-stat"><span class="metric-label">Lương tối thiểu vùng I · 2026</span><strong>5,31 triệu ₫</strong><p class="muted">Mức tối thiểu theo tháng; áp dụng từ 01/01/2026, không phải benchmark trung bình.</p><a href="https://baochinhphu.vn/tang-luong-toi-thieu-vung-tu-1-1-2026-102251110175033018.htm" target="_blank" rel="noopener">Báo Chính phủ ↗</a></article><article class="market-stat"><span class="metric-label">Nhu cầu lao động</span><strong>Công nghiệp & dịch vụ</strong><p class="muted">Bản tin GSO 6 tháng 2026: công nghiệp/xây dựng và dịch vụ đều tăng việc làm so với cùng kỳ.</p><a href="https://www.nso.gov.vn/tin-tuc-thong-ke/2026/07/thong-cao-bao-chi-ve-tinh-hinh-lao-dong-viec-lam-quy-ii-va-6-thang-dau-nam-2026/" target="_blank" rel="noopener">GSO ↗</a></article><article class="market-stat"><span class="metric-label">Vị trí phổ thông cần survey</span><strong>Kho · Sản xuất · Vệ sinh</strong><p class="muted">Mở truy vấn tin tuyển dụng công khai theo địa bàn để thu thập lương, ca làm và phụ cấp.</p><a href="https://www.google.com/search?q=tuy%E1%BB%83n+c%C3%B4ng+nh%C3%A2n+kho+v%E1%BB%87+sinh+b%E1%BA%A3o+v%E1%BB%87+Vi%E1%BB%87t+Nam" target="_blank" rel="noopener">Tìm nguồn ↗</a></article></div><p class="market-source">Nguồn công khai được dẫn liên kết để người dùng tự kiểm tra. Mức lương tuyển dụng không đồng nghĩa với phí dịch vụ BPO; các dự án mẫu và số liệu dashboard khác do người dùng nhập, không được giả định là số liệu toàn thị trường.</p></div>

${marketSignalsPanel()}
${recentActivityPanel()}`
}
function recentActivityItems(){
 const all=[...db.projects.map(x=>({date:x.updated||'',title:x.customer||x.name||'Dự án chưa đặt tên',desc:`${x.region||'Chưa có khu vực'} · ${x.positions||x.position||'Chưa có vị trí'} · ${x.status||'Chưa cập nhật'}`,type:'project',typeLabel:'Dự án',id:x.id})),...db.pricing.map(x=>({date:x.updated||'',title:x.position||'Benchmark chưa đặt tên',desc:`${x.region||'Chưa có khu vực'} · ${x.verified||'Chưa xác minh'}`,type:'pricing',typeLabel:'Benchmark',id:x.id})),...db.leads.map(x=>({date:x.updated||'',title:x.name||'Cơ hội chưa đặt tên',desc:`${x.region||'Chưa có khu vực'} · ${x.status||'Chưa cập nhật'}`,type:'lead',typeLabel:'Cơ hội',id:x.id})),...db.clients.map(x=>({date:x.updated||'',title:x.name||'Khách hàng chưa đặt tên',desc:`${x.region||'Chưa có khu vực'} · ${x.industry||'Chưa có ngành'} · ${x.status||x.type||'Chưa cập nhật'}`,type:'client',typeLabel:'Khách hàng',id:x.id}))];
 return all.filter(x=>recentFilterType==='all'||x.type===recentFilterType).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
}
function recentActivityPanel(){
 const items=recentActivityItems(),visible=recentShowAll?items.slice(0,20):items.slice(0,3);
 return `<section class="panel recent-panel" id="recentActivityPanel"><div class="panel-head recent-head"><div><h3>Cập nhật gần đây</h3><p>Theo dõi hồ sơ vừa thay đổi — lọc riêng, không làm dài danh sách chính</p></div><label class="recent-filter-label">Loại hồ sơ<select id="recentTypeFilter" class="control"><option value="all" ${recentFilterType==='all'?'selected':''}>Tất cả</option><option value="project" ${recentFilterType==='project'?'selected':''}>Dự án</option><option value="client" ${recentFilterType==='client'?'selected':''}>Khách hàng</option><option value="pricing" ${recentFilterType==='pricing'?'selected':''}>Benchmark / phí</option><option value="lead" ${recentFilterType==='lead'?'selected':''}>Cơ hội</option></select></label></div>${visible.length?`<div class="activity-list">${visible.map(x=>`<div class="activity"><div class="activity-dot">${x.type==='project'?'▤':x.type==='pricing'?'↗':x.type==='client'?'▣':'◎'}</div><div class="activity-body"><b>${esc(x.title)}</b><p>${esc(x.desc)}</p></div><span class="activity-meta"><small>${esc(x.typeLabel)}</small><time>${esc(x.date||'Chưa có ngày')}</time></span></div>`).join('')}</div>${items.length>3?`<div class="recent-actions"><span class="cell-sub">${Math.min(visible.length,20)} / ${items.length} hồ sơ</span><button class="text-btn" id="toggleRecentMore">${recentShowAll?'Thu gọn':'Xem thêm'}</button></div>`:''}`:`<div class="empty-hint">Chưa có hồ sơ thuộc bộ lọc này.</div>`}</section>`;
}
function refreshRecentActivity(){const panel=$('#recentActivityPanel');if(panel)panel.outerHTML=recentActivityPanel()}
function finderAutocomplete(id, label, items, placeholder){return `<label class="finder-field"><span>${label}</span><div class="finder-autocomplete"><input class="control" id="${id}" autocomplete="off" autocapitalize="off" spellcheck="false" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}Suggestions" placeholder="${placeholder}"><div class="finder-suggestions" id="${id}Suggestions" role="listbox" aria-label="${label}"></div></div></label>`}
function marketFinder(){const values=marketFinderCatalogs();return `<section class="panel market-finder" id="marketFinder"><div class="panel-head"><div><div class="eyebrow">TRA CỨU 3 CHIỀU</div><h3>Vị trí công việc × Khu vực × Ngành nghề</h3><p>Kết quả chỉ lấy từ hồ sơ thực tế đang lưu trên thiết bị: dự án, benchmark, khách hàng và cơ hội. Danh mục gợi ý được tạo từ dữ liệu này, không phải dữ liệu thị trường mẫu.</p></div><span class="finder-mark">↔</span></div><div class="finder-grid">${finderAutocomplete('finderPosition','⌕ Vị trí công việc',values.positions,values.positions.length?'Tìm trong vị trí đã có…':'Chưa có vị trí — hãy nhập hoặc import dữ liệu')}${finderAutocomplete('finderRegion','⌖ Khu vực',values.regions,values.regions.length?'Tìm trong khu vực đã có…':'Chưa có khu vực — hãy nhập hoặc import dữ liệu')}${finderAutocomplete('finderIndustry','▦ Ngành nghề / lĩnh vực',values.industries,values.industries.length?'Tìm trong ngành đã có…':'Chưa có ngành — hãy nhập hoặc import dữ liệu')}</div><div class="finder-actions"><span class="cell-sub">Không có dữ liệu mẫu được tự thêm. Mỗi kết quả đều gắn với một bản ghi thực tế trong cơ sở dữ liệu cục bộ.</span><button class="secondary-btn" id="clearMarketFinder">Xóa tìm kiếm</button></div><div id="marketFinderResults">${marketFinderResults()}</div></section>`}
function closeFinderSuggestions(exceptId=''){for(const id of ['finderPosition','finderRegion','finderIndustry']){if(id===exceptId)continue;const input=$('#'+id),box=$('#'+id+'Suggestions');if(box){box.classList.remove('open');box.innerHTML=''}if(input)input.setAttribute('aria-expanded','false')}}
function renderFinderSuggestions(input, forceOpen=true){if(!input)return;const id=input.id,box=$('#'+id+'Suggestions');if(!box)return;const catalogs=marketFinderCatalogs(),key={finderPosition:'positions',finderRegion:'regions',finderIndustry:'industries'}[id],all=catalogs[key]||[],q=finderNorm(input.value);const options=(q?all.filter(x=>finderNorm(x).includes(q)):all).slice(0,8);if(!forceOpen||!all.length){box.classList.remove('open');box.innerHTML='';input.setAttribute('aria-expanded','false');return}box.innerHTML=options.length?options.map((value,i)=>`<button type="button" class="finder-suggestion" role="option" aria-selected="false" data-finder-suggestion="${id}" data-value="${esc(value)}" data-index="${i}">${esc(value)}</button>`).join(''):`<div class="finder-suggestion-empty">Không có gợi ý phù hợp. Bà vẫn có thể nhập giá trị mới.</div>`;box.classList.add('open');input.setAttribute('aria-expanded','true')}
function marketFinderCatalogs(){
 const positions=[],regions=[],industries=[];
 const add=(target,value)=>{String(value||'').split(/\r?\n|[,;|]+/).map(x=>x.trim()).filter(Boolean).forEach(x=>target.push(x))};
 for(const p of db.projects){add(positions,p.positions||p.position);add(regions,p.region);add(industries,p.industry)}
 for(const p of db.pricing){add(positions,p.position);add(regions,p.region);add(industries,p.industry)}
 for(const c of db.clients){add(positions,c.services||c.positions);add(regions,c.region);add(industries,c.industry)}
 for(const l of db.leads){add(positions,l.potential||l.positions);add(regions,l.region);add(industries,l.industry)}
 const uniq=a=>[...new Set(a)].sort((a,b)=>a.localeCompare(b,'vi'));
 return {positions:uniq(positions),regions:uniq(regions),industries:uniq(industries)};
}
function finderNorm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().trim()}
function marketFinderResults(){
const roleQ=finderNorm($('#finderPosition')?.value),regionQ=finderNorm($('#finderRegion')?.value),industryQ=finderNorm($('#finderIndustry')?.value);
const hasQuery=!!(roleQ||regionQ||industryQ);
if(!hasQuery)return `<div class="finder-idle"><span class="finder-idle-icon">⌕</span><div><b>Bắt đầu bằng một điều kiện</b><p>Chọn hoặc nhập <strong>vị trí</strong>, <strong>khu vực</strong> hoặc <strong>ngành nghề</strong>. Kết quả liên quan sẽ xuất hiện sau khi bà nhập bộ lọc; mặc định không tải toàn bộ hồ sơ.</p></div></div>`;
const north=['ha noi','hai phong','bac ninh','bac giang'],central=['da nang','hue','quang nam'],south=['ho chi minh','tp ho chi minh','cu chi','long an','binh duong','dong nai','vsip'];
function regionMatches(record,q){if(!q)return true;const r=finderNorm([record.region,record.district,record.ward,record.notes].join(' '));if(r.includes(q))return true;const aliases={'mien bac':north,'mien trung':central,'mien nam':south,'tphcm':['ho chi minh','tp ho chi minh','cu chi'],'hcm':['ho chi minh','tp ho chi minh','cu chi'],'sai gon':['ho chi minh','tp ho chi minh','cu chi']};const list=aliases[q];return !!list&&list.some(x=>r.includes(finderNorm(x)))}
const records=[];
for(const p of db.projects)records.push({kind:'Dự án',type:'project',id:p.id,title:p.customer||p.name||p.id,position:p.positions||p.position||'',region:p.region||'',district:p.district||'',ward:p.ward||'',industry:p.industry||'',status:p.status||'Chưa xác định',headcount:p.headcount,notes:p.notes||'',raw:p});
for(const p of db.pricing)records.push({kind:'Benchmark vị trí/phí',type:'pricing',id:p.id,title:p.position||p.model||p.id,position:p.position||'',region:p.region||'',industry:p.industry||'',status:p.verified||'Chưa xác minh',headcount:'',notes:[p.model,p.source,p.notes].filter(Boolean).join(' '),raw:p});
for(const l of db.leads)records.push({kind:'Cơ hội',type:'lead',id:l.id,title:l.name||l.potential||l.id,position:l.potential||l.positions||'',region:l.region||'',industry:l.industry||'',status:l.status||'Chưa xác định',headcount:'',notes:[l.signal,l.notes].filter(Boolean).join(' '),raw:l});
for(const c of db.clients)records.push({kind:'Khách hàng',type:'client',id:c.id,title:c.name||c.id,position:c.services||c.positions||'',region:c.region||'',industry:c.industry||'',status:c.status||c.type||'Chưa xác định',headcount:'',notes:c.notes||'',raw:c});
const matches=records.filter(r=>{const roleText=finderNorm([r.position,r.title,r.notes].join(' ')),industryText=finderNorm([r.industry].join(' '));return (!roleQ||roleText.includes(roleQ))&&regionMatches(r,regionQ)&&(!industryQ||industryText.includes(industryQ))});
const split=vals=>[...new Set(vals.flatMap(v=>String(v||'').split(/[,;\/|]+/).map(x=>x.trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'vi'));
const positions=split(matches.map(r=>r.position)),regions=split(matches.map(r=>[r.region,r.district,r.ward].filter(Boolean).join(' · '))),industries=split(matches.map(r=>r.industry));
const openButton=r=>`<button class="text-btn finder-open" data-finder-open="${r.type}" data-id="${esc(r.id)}">${esc(r.title)}</button>`;
const visibleMatches=finderShowAll?matches.slice(0,100):matches.slice(0,8);
return `<div class="finder-summary"><strong>${matches.length}</strong><span>hồ sơ khớp bộ lọc · lấy từ dữ liệu thực tế đang lưu</span></div><div class="finder-results-grid"><article class="finder-result"><div class="finder-result-head"><span>01</span><b>Vị trí công việc</b><small>${positions.length}</small></div>${positions.length?`<div class="finder-chips">${positions.slice(0,12).map(x=>`<button class="finder-chip" data-finder-fill="position" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>${positions.length>12?`<small class="cell-sub">+ ${positions.length-12} vị trí khác</small>`:''}`:'<p class="muted">Chưa có vị trí phù hợp.</p>'}</article><article class="finder-result"><div class="finder-result-head"><span>02</span><b>Khu vực có dữ liệu</b><small>${regions.length}</small></div>${regions.length?`<div class="finder-chips">${regions.slice(0,12).map(x=>`<button class="finder-chip" data-finder-fill="region" data-value="${esc(x.split(' · ')[0])}">${esc(x)}</button>`).join('')}</div>${regions.length>12?`<small class="cell-sub">+ ${regions.length-12} khu vực khác</small>`:''}`:'<p class="muted">Chưa có khu vực phù hợp.</p>'}</article><article class="finder-result"><div class="finder-result-head"><span>03</span><b>Ngành nghề / lĩnh vực</b><small>${industries.length}</small></div>${industries.length?`<div class="finder-chips">${industries.slice(0,12).map(x=>`<button class="finder-chip" data-finder-fill="industry" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>${industries.length>12?`<small class="cell-sub">+ ${industries.length-12} ngành khác</small>`:''}`:'<p class="muted">Chưa có ngành nghề phù hợp.</p>'}</article></div>${matches.length?`<div class="finder-records-head"><b>Hồ sơ phù hợp</b><span>${visibleMatches.length} / ${Math.min(matches.length,100)} hiển thị</span></div><div class="table-wrap finder-table"><table><thead><tr><th>Loại hồ sơ / tên</th><th>Vị trí / dịch vụ</th><th>Khu vực</th><th>Ngành / lĩnh vực</th><th>Trạng thái</th></tr></thead><tbody>${visibleMatches.map(r=>`<tr><td><div class="cell-sub">${esc(r.kind)} · ${esc(r.id)}</div>${openButton(r)}</td><td style="white-space:normal">${esc(r.position||'—')}</td><td>${esc([r.region,r.district,r.ward].filter(Boolean).join(' · ')||'—')}</td><td>${esc(r.industry||'—')}</td><td>${esc(r.status||'—')}</td></tr>`).join('')}</tbody></table></div>${matches.length>8&&matches.length<=100?`<div class="finder-more-row"><button class="secondary-btn" id="toggleFinderMore">${finderShowAll?'Thu gọn danh sách':'Xem tất cả hồ sơ phù hợp'}</button></div>`:matches.length>100?`<p class="cell-sub">Đang hiển thị tối đa 100 trên ${matches.length} hồ sơ phù hợp.</p>`:''}`:'<div class="empty-hint">Không tìm thấy hồ sơ phù hợp. Thử xóa bớt điều kiện hoặc kiểm tra dữ liệu đã nhập ở Dự án, Khách hàng, Lương & phí dịch vụ và Cơ hội.</div>'}`
}
function updateMarketFinder(){finderShowAll=false;const out=$('#marketFinderResults');if(out)out.innerHTML=marketFinderResults()}
function tableShell(head,rows,empty,cols){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${cols}" class="muted" style="text-align:center;padding:30px">${empty}</td></tr>`}</tbody></table></div>`}
function projectsPage(q){let list=db.projects.filter(x=>JSON.stringify(x).toLowerCase().includes(q));const wards=[...new Set(db.projects.map(x=>x.ward).filter(Boolean))].sort();return `<div class="section-head"><div><h2>Dự án & nhân sự</h2><p>Tra cứu theo tỉnh/thành, quận/huyện hoặc phường/xã, ngành và trạng thái dự án.</p></div><button class="primary-btn" data-add="project">＋ Thêm dự án</button></div><div class="toolbar">${regionFilter()}<select class="control" id="districtFilter"><option value="">Tất cả quận/huyện</option>${[...new Set(db.projects.map(x=>x.district).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="control" id="wardFilter"><option value="">Tất cả phường/xã</option>${wards.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="control" id="statusFilter"><option value="">Tất cả trạng thái</option><option>Đang chạy</option><option>Đang triển khai</option><option>Tạm dừng</option><option>Đã kết thúc</option><option>Cần xác minh</option></select><select class="control" id="industryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.projects.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="secondary-btn" id="clearProjectFilters">Xóa lọc</button></div><p class="cell-sub filter-count" id="filterResultCount">${list.length} dự án</p><div id="projectTable">${projectRows(list)}</div><p class="cell-sub" style="margin-top:12px">Bổ sung quận/huyện và phường/xã trong hồ sơ dự án để lọc chi tiết.</p>`}
function projectRows(list){return tableShell(['Khách hàng / dự án','Khu vực · Ngành','Vị trí cung cấp','Nhân sự','Lương tham khảo','Phí dịch vụ','Trạng thái',''],list.map(x=>`<tr><td><button class="project-open" data-project-detail="${esc(x.id)}"><span class="cell-main">${esc(x.customer)}</span><span class="cell-sub">${esc(x.id)} · ${esc(x.service)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc([x.district,x.ward].filter(Boolean).join(' · '))}</div><div class="cell-sub">${esc(x.industry)}</div></td><td style="max-width:230px;white-space:normal">${esc(x.positions)}</td><td class="price">${num(x.headcount)}</td><td class="price">${fmt(x.salary)}<div class="cell-sub">${esc(x.salaryUnit||'Theo tháng (VNĐ/tháng)')}</div></td><td class="price">${formatAmount(x.fee,x.feeUnit)}<div class="cell-sub">${esc(x.feeUnit||'VNĐ/người/tháng')}${x.taxRate!==''&&x.taxRate!=null?' · VAT '+esc(x.taxRate)+'%':''}</div></td><td>${statusPill(x.status)}</td><td><div class="row-actions"><button class="small-btn" data-edit="project" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="project" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''), 'Không tìm thấy dự án phù hợp.',8)}
function clientsPage(q){let list=db.clients.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Hồ sơ khách hàng</h2><p>Một hồ sơ cho mỗi doanh nghiệp, bao gồm khách hàng đang chạy và tài khoản mục tiêu.</p></div><button class="primary-btn" data-add="client">＋ Thêm khách hàng</button></div><div class="toolbar">${regionFilter()}<select class="control" id="typeFilter"><option value="">Tất cả nhóm</option><option>Khách hàng hiện tại</option><option>Khách hàng tiềm năng</option><option>Đối tác</option></select><select class="control" id="clientStatusFilter"><option value="">Tất cả trạng thái</option><option>Đang hợp tác</option><option>Đang tiếp cận</option><option>Cần nghiên cứu</option><option>Không phù hợp</option></select><button class="secondary-btn" id="clearClientFilters">Xóa lọc</button></div><p class="cell-sub filter-count" id="filterResultCount">${list.length} khách hàng</p><div id="clientTable">${clientRows(list)}</div>`}
function clientRows(list){return tableShell(['Doanh nghiệp','Khu vực · Ngành','Nhóm khách hàng','Dịch vụ quan tâm','Liên hệ / Website','Trạng thái','Nguồn',''],list.map(x=>`<tr><td><button type="button" class="record-open" data-client-detail="${esc(x.id)}"><span class="cell-main">${esc(x.name)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td>${esc(x.type)}</td><td style="white-space:normal;max-width:190px">${esc(x.services)}</td><td>${esc(x.contact||'—')}${x.website?`<div class="cell-sub"><a class="source-link" href="${esc(x.website)}" target="_blank" rel="noopener">Website ↗</a></div>`:''}</td><td>${statusPill(x.status)}</td><td>${esc(x.source||'—')}</td><td><div class="row-actions"><button class="small-btn" data-edit="client" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="client" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có khách hàng phù hợp.',8)}
function pricingPage(q){let list=db.pricing.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Lương & phí dịch vụ</h2><p>So sánh chi phí nhân sự và giá bán dịch vụ theo vị trí, khu vực và mô hình BPO.</p></div><button class="primary-btn" data-add="pricing">＋ Thêm benchmark</button></div><div class="callout"><b>Lưu ý:</b> Chỉ sử dụng benchmark có nguồn, ngày cập nhật và trạng thái xác minh rõ ràng. Dữ liệu chưa xác minh không nên được coi là báo giá thị trường chính thức.</div><div class="toolbar">${regionFilter()}<select class="control" id="verifiedFilter"><option value="">Mọi trạng thái nguồn</option><option>Đã xác minh</option><option>Chưa xác minh</option><option>Cần cập nhật</option></select><select class="control" id="pricingIndustryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.pricing.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><p class="cell-sub filter-count" id="filterResultCount">${list.length} benchmark</p><div id="pricingTable">${pricingRows(list)}</div>`}
function pricingRows(list){return tableShell(['Vị trí','Khu vực · Ngành','Khoảng lương','Phí dịch vụ','Mô hình dịch vụ','Nguồn / cập nhật','Xác minh',''],list.map(x=>`<tr><td><button type="button" class="record-open" data-pricing-detail="${esc(x.id)}"><span class="cell-main">${esc(x.position)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td class="price">${fmt(x.salaryMin)} – ${fmt(x.salaryMax)}<div class="cell-sub">${esc(x.salaryUnit||'Theo tháng (VNĐ/tháng)')}</div></td><td class="price">${formatAmount(x.feeMin,x.feeUnit)} – ${formatAmount(x.feeMax,x.feeUnit)}<div class="cell-sub">${esc(x.feeUnit||x.feeType||'VNĐ/người/tháng')}${x.taxRate!==''&&x.taxRate!=null?' · VAT '+esc(x.taxRate)+'%':''}</div></td><td>${esc(x.service)}</td><td>${x.sourceUrl?`<a class="source-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Mở nguồn ↗</a>`:esc(x.source||'—')}<div class="cell-sub">Cập nhật: ${esc(x.updated||'—')}</div></td><td>${statusPill(x.verified)}</td><td><div class="row-actions"><button class="small-btn" data-edit="pricing" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="pricing" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có benchmark phù hợp.',8)}
function leadsPage(q){let list=db.leads.filter(x=>JSON.stringify(x).toLowerCase().includes(q));return `<div class="section-head"><div><h2>Cơ hội tiềm năng</h2><p>Ghi nhận doanh nghiệp mục tiêu, tín hiệu tuyển dụng công khai và bước tiếp theo của Sales.</p></div><button class="primary-btn" data-add="lead">＋ Thêm cơ hội</button></div><div class="callout"><b>Quy trình đề xuất:</b> Tìm nguồn công khai → lưu URL và ngày cập nhật → xác minh công ty/vị trí → ghi nhận người phụ trách → tiếp cận theo quy trình của công ty. Không thu thập dữ liệu cá nhân nhạy cảm hoặc nội dung riêng tư.</div><div class="toolbar">${regionFilter()}<select class="control" id="leadRecordTypeFilter"><option value="">Mọi loại hồ sơ</option><option>Dự án đối thủ</option><option>Dự án tiềm năng</option><option>Cơ hội khách hàng</option></select><select class="control" id="leadStatusFilter"><option value="">Tất cả trạng thái</option><option>Chưa tiếp cận</option><option>Cần xác minh</option><option>Đang tiếp cận</option><option>Đang đàm phán</option><option>Đã chuyển đổi</option><option>Không phù hợp</option></select><select class="control" id="leadIndustryFilter"><option value="">Tất cả ngành</option>${[...new Set(db.leads.map(x=>x.industry).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><p class="cell-sub filter-count" id="filterResultCount">${list.length} cơ hội</p><div id="leadTable">${leadRows(list)}</div>`}
function leadRows(list){return tableShell(['Loại hồ sơ','Doanh nghiệp / mục tiêu','Khu vực · Ngành','Nhu cầu dự kiến','Tín hiệu / nguồn','Điểm ưu tiên','Sales phụ trách','Trạng thái',''],list.map(x=>`<tr><td>${esc(x.recordType||'Cơ hội khách hàng')}</td><td><button type="button" class="record-open" data-lead-detail="${esc(x.id)}"><span class="cell-main">${esc(x.name)}</span><span class="cell-sub">${esc(x.id)} · Xem chi tiết ↗</span></button><div class="cell-sub">${x.sourceUrl?`<a class="source-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Mở nguồn ↗</a>`:esc(x.source||'Chưa có nguồn')}</div></td><td>${esc(x.region)}<div class="cell-sub">${esc(x.industry)}</div></td><td style="white-space:normal;max-width:180px">${esc(x.potential)}</td><td style="white-space:normal;max-width:220px">${esc(x.signal)}<div class="cell-sub">Liên hệ: ${esc(x.contact||'Chưa cập nhật')}</div></td><td><span class="lead-score">${'★'.repeat(Math.max(0,Math.min(5,Number(x.score||0))))}${'☆'.repeat(5-Math.max(0,Math.min(5,Number(x.score||0))))}</span></td><td>${esc(x.owner||'Chưa phân công')}</td><td>${statusPill(x.status)}</td><td><div class="row-actions"><button class="small-btn" data-edit="lead" data-id="${esc(x.id)}">Sửa</button><button class="small-btn" data-delete="lead" data-id="${esc(x.id)}">×</button></div></td></tr>`).join(''),'Chưa có cơ hội phù hợp.',9)}
function researchPage(){return `<div class="section-head"><div><h2>Nghiên cứu & survey thị trường</h2><p>Tạo truy vấn theo vị trí, khu vực và ngành; mở nguồn công khai để kiểm tra rồi lưu kết quả bằng tay vào cơ sở dữ liệu cục bộ.</p></div></div><div class="callout"><b>Cách dùng:</b> nhập thông tin cần khảo sát → mở các nguồn tìm kiếm → xác minh tin tuyển dụng, ngày đăng, địa điểm và đơn vị → lưu thông tin vào mục Lương & phí hoặc Cơ hội tiềm năng. App không tự đọc dữ liệu từ các trang bên ngoài; các nguồn có thể yêu cầu đăng nhập riêng.</div><form id="researchForm" class="research-form"><label>Từ khóa / vị trí<input name="query" required placeholder="Ví dụ: warehouse staff, customer service, telesales"></label><label>Khu vực<input name="region" placeholder="TP. Hồ Chí Minh, Bình Dương..."></label><label>Ngành<input name="industry" placeholder="Logistics, sản xuất, retail..."></label><button class="primary-btn" type="submit">⌕ Tạo khảo sát & mở nguồn</button></form><div id="researchStatus" class="callout" style="margin-top:16px">Không cần API key. App tạo các truy vấn tìm kiếm sẵn; bạn chọn nguồn, kiểm tra thông tin và nhập dữ liệu xác minh vào app.</div><div id="researchResults" class="research-grid"></div><h3 style="margin-top:26px">Nguồn khảo sát nhanh</h3><div class="research-grid">${[['Google','Tìm website doanh nghiệp và tin tuyển dụng'],['LinkedIn','Tìm trang công ty và tin tuyển dụng công khai'],['VietnamWorks','Tìm tin tuyển dụng theo vị trí'],['CareerViet','Tìm nhu cầu tuyển dụng tại Việt Nam'],['Indeed','Tìm vị trí đang tuyển'],['TopCV','Tìm tin tuyển dụng và mặt bằng vị trí']].map(x=>`<article class="research-result"><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><p class="cell-sub">Từ khóa được bổ sung khi bạn gửi khảo sát phía trên.</p></article>`).join('')}</div>`}
function settingsPage(){const st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');const theme=st.theme||'modern';const themes=[['modern','Mặc định · Hiện đại','Chuyên nghiệp, cân bằng','#6941c6','#eef0ff','✦'],['dark','Tối · Dark','Dịu mắt khi làm việc ban đêm','#8b7cff','#211d30','☾'],['fresh','Tươi trẻ, năng động','Sáng sủa, tươi mới, nhiều năng lượng','#0ca678','#e9fbef','↗'],['romantic','Lãng mạn, thơ mộng','Nhẹ nhàng, tinh tế, đầy cảm hứng','#d9468d','#fff0f7','♡'],['auto','Theo hệ thống','Tự động theo giao diện thiết bị','#4968d8','#edf3ff','◐']];return `<div class="section-head"><div><h2>Cá nhân hóa giao diện</h2><p>Chọn phong cách cho toàn bộ ứng dụng. Thiết lập được lưu trên thiết bị này.</p></div></div><section class="theme-picker-panel"><div class="theme-choice-grid">${themes.map(([id,name,desc,color,soft,icon])=>`<button type="button" class="theme-choice ${theme===id?'selected':''}" data-theme-choice="${id}" style="--theme-preview:${color};--theme-preview-soft:${soft}" aria-pressed="${theme===id}"><span class="theme-choice-icon">${icon}</span><span class="theme-choice-copy"><strong>${name}</strong><small>${desc}</small><span class="theme-mini-swatches"><i></i><i></i><i></i><i></i></span></span><span class="theme-choice-check">✓</span></button>`).join('')}</div></section><div class="settings-grid"><section class="setting-card"><h3>Cỡ chữ</h3><p class="muted">Điều chỉnh độ dễ đọc trên điện thoại và máy tính.</p><label for="fontSelect">Kích thước văn bản</label><select id="fontSelect" class="control"><option value="15px" ${!st.font||st.font==='15px'?'selected':''}>Tiêu chuẩn</option><option value="16px" ${st.font==='16px'?'selected':''}>Lớn</option><option value="14px" ${st.font==='14px'?'selected':''}>Nhỏ</option></select><button class="secondary-btn" id="resetSettings" style="margin-top:18px">Khôi phục mặc định</button></section><section class="setting-card"><h3>Màu nhấn tùy chỉnh</h3><p class="muted">Có thể chọn màu riêng cho nút, liên kết và điểm nhấn mà vẫn giữ nền của theme.</p><div class="swatches">${['#6941c6','#2563eb','#0ca678','#e69b16','#d9468d','#344054'].map(color=>`<button type="button" class="swatch ${((st.color||'')===color)?'selected':''}" style="background:${color}" data-color="${color}" aria-label="Màu ${color}" title="${color}"></button>`).join('')}</div><button class="text-btn" id="resetAccent" type="button">Dùng lại màu của theme</button></section></div><section class="panel backup-settings-panel" style="margin-top:18px"><div class="panel-head"><div><h3>Save / Load backup data</h3><p>Lưu hoặc khôi phục toàn bộ khách hàng, dự án, benchmark và cơ hội trên thiết bị này.</p></div><span class="theme-choice-icon" aria-hidden="true">▣</span></div><div class="backup-actions"><button type="button" class="primary-btn" id="saveBackupJsonBtn">⇩ Lưu bản sao lưu JSON</button><button type="button" class="secondary-btn" id="saveEncryptedBackupBtn">🔒 Lưu bản sao lưu mã hóa</button><button type="button" class="secondary-btn" id="loadBackupBtn">⇧ Tải / khôi phục bản sao lưu</button></div><p class="muted">File JSON thường không được mã hóa. File mã hóa dùng AES-256-GCM và yêu cầu mật khẩu khi khôi phục. Khôi phục sẽ thay thế dữ liệu hiện tại; hãy lưu một bản sao trước khi thực hiện.</p></section><div class="callout" style="margin-top:16px"><b>Mẹo:</b> Chọn một thẻ theme để đổi màu toàn ứng dụng ngay lập tức. Màu nhấn tùy chỉnh có thể ghi đè màu nhấn mặc định, nhưng không làm mất phong cách nền của theme.</div>`}
function applySettings(){let st={};try{st=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}')}catch{}let theme=st.theme||'modern';if(theme==='light')theme='modern';if(!['modern','dark','fresh','romantic','auto'].includes(theme))theme='modern';const systemDark=!!(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);const effectiveTheme=theme==='auto'?(systemDark?'dark':'modern'):theme;const palettes={modern:{accent:'#6941c6',bg:'#f7f7ff',ink:'#172554',muted:'#737b98',line:'#e5e7f5',surface:'#ffffff',sidebar:'#21134d',sidebarText:'#e9e4ff',sidebarActive:'#37236e',welcome1:'#4f46e5',welcome2:'#7c3aed',soft:'#f0edff'},dark:{accent:'#8b7cff',bg:'#11101a',ink:'#f0ecfa',muted:'#b5aec7',line:'#302b40',surface:'#1b1828',sidebar:'#0c0b13',sidebarText:'#d8d2ec',sidebarActive:'#29213f',welcome1:'#251b43',welcome2:'#573a94',soft:'#29213f'},fresh:{accent:'#0ca678',bg:'#f1fbf5',ink:'#163b32',muted:'#648178',line:'#dcefe4',surface:'#ffffff',sidebar:'#075642',sidebarText:'#dff8ec',sidebarActive:'#087a5d',welcome1:'#07966c',welcome2:'#62bd42',soft:'#e3f8e9'},romantic:{accent:'#d9468d',bg:'#fff5fa',ink:'#4a2441',muted:'#92758a',line:'#f4dce9',surface:'#ffffff',sidebar:'#592449',sidebarText:'#ffe7f2',sidebarActive:'#79315f',welcome1:'#d9468d',welcome2:'#9d6de8',soft:'#ffe7f2'}};const p=palettes[effectiveTheme]||palettes.modern;const c=st.color||p.accent;const root=document.documentElement;root.dataset.theme=effectiveTheme;root.style.colorScheme=effectiveTheme==='dark'?'dark':'light';const vars={'--ink':p.ink,'--muted':p.muted,'--line':p.line,'--bg':p.bg,'--white':p.surface,'--green':c,'--accent':c,'--accent-soft':`color-mix(in srgb, ${c} 12%, transparent)`,'--accent-border':`color-mix(in srgb, ${c} 38%, transparent)`,'--accent-strong':`color-mix(in srgb, ${c} 82%, ${p.sidebar})`,'--accent-tint':`color-mix(in srgb, ${c} 9%, ${p.surface})`,'--accent-dark':p.sidebar,'--accent-mid':p.sidebarActive,'--sidebar-bg':p.sidebar,'--sidebar-text':p.sidebarText,'--sidebar-active':p.sidebarActive,'--welcome-start':p.welcome1,'--welcome-end':p.welcome2,'--surface-alt':p.soft,'--amber':effectiveTheme==='romantic'?'#fff0d8':effectiveTheme==='fresh'?'#fff6d8':'#fff1d5','--red':effectiveTheme==='romantic'?'#ffe4ee':'#fde7e5'};Object.entries(vars).forEach(([k,v])=>root.style.setProperty(k,v));document.body.style.fontSize=st.font||'15px';document.body.classList.toggle('theme-dark',effectiveTheme==='dark');document.body.classList.toggle('theme-fresh',effectiveTheme==='fresh');document.body.classList.toggle('theme-romantic',effectiveTheme==='romantic');} 

function dataPage(){return `<div class="section-head"><div><h2>Nhập / xuất Excel</h2><p>Nhập dữ liệu thị trường từ bảng tính hoặc xuất dữ liệu để phân tích.</p></div></div><div class="callout"><b>Quy trình:</b> tải template → giữ nguyên tên cột ở dòng đầu → nhập dữ liệu → upload file .xlsx hoặc .csv. App xem trước số dòng và kiểm tra dữ liệu trước khi nhập. Để sao lưu và khôi phục toàn bộ dữ liệu, mở Cài đặt ⚙ → Save / Load backup data.</div><div class="data-actions"><button class="primary-btn" id="downloadTemplate">⇩ Tải template Excel</button><button class="secondary-btn" id="exportExcel">Xuất dữ liệu hiện tại (.xlsx)</button></div><section class="panel"><h3>Upload file Excel</h3><p class="muted">Hỗ trợ file template của app và tự nhận diện bảng dữ liệu có sẵn với các cột Khu vực, Lĩnh vực của KH, Tên Dự án (tên KH), Vị trí nhân sự, Phí dịch vụ. File CSV dùng được offline.</p><div class="dropzone"><p>Chọn file Excel đã cập nhật (.xlsx)</p><input type="file" id="excelFile" aria-label="Chọn tệp Excel hoặc CSV" accept=".xlsx,.xls,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel"></div><div id="excelPreview" style="margin-top:14px"></div><button class="primary-btn" id="commitExcel" disabled>Kiểm tra và nhập dữ liệu</button></section><div class="panel" style="margin-top:16px"><h3>Cấu trúc sheet</h3><p><b>Projects:</b> customer, region, industry, status, positions, headcount, service, salary, salaryUnit, fee, feeUnit, taxRate, updated, notes</p><p><b>Clients:</b> name, region, industry, type, status, website, sourceUrl, notes</p><p><b>SalaryFees:</b> position, region, industry, salaryMin, salaryMax, salaryUnit, feeMin, feeMax, feeUnit, taxRate, model, service, source, sourceUrl, verified, updated, notes. Dùng cho lao động phổ thông, sản xuất, kho vận, vệ sinh, bảo vệ, giao nhận, CSKH, telesales, back office và IT.</p><p><b>Leads:</b> name, region, industry, potential, signal, source, sourceUrl, contact, owner, score, status, updated, notes</p></div>`}
let pendingExcel=null;
function csvCell(v){const s=String(v??'');return '"'+s.replace(/"/g,'""')+'"'}
function downloadBlob(name,blob){if(window.AndroidDownloads&&typeof window.AndroidDownloads.saveFile==='function'){const reader=new FileReader();reader.onload=()=>{try{const b64=String(reader.result).split(',')[1]||'';window.AndroidDownloads.saveFile(name,blob.type||'application/octet-stream',b64)}catch(e){showToast('Không thể mở hộp thoại lưu tệp: '+(e.message||e))}};reader.onerror=()=>showToast('Không đọc được dữ liệu để lưu tệp.');reader.readAsDataURL(blob);return}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},10000)}
function downloadText(name,text,type='text/csv;charset=utf-8'){downloadBlob(name,new Blob(['\ufeff',text],{type}))}
function downloadXlsx(wb,name){const mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';if(window.AndroidDownloads&&window.XLSX){window.AndroidDownloads.saveFile(name,mime,XLSX.write(wb,{bookType:'xlsx',type:'base64'}));return}const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});downloadBlob(name,new Blob([bytes],{type:mime}))}
function downloadBundledTemplate(){if(window.AndroidDownloads&&typeof window.AndroidDownloads.saveBundledTemplate==='function'){window.AndroidDownloads.saveBundledTemplate();return}fetch('assets/BPO-Intelligence-Hub-Excel-Template.xlsx').then(r=>{if(!r.ok)throw Error('Không tải được template tích hợp');return r.blob()}).then(b=>downloadBlob('BPO-Intelligence-Hub-Excel-Template.xlsx',b)).catch(()=>{downloadText('BPO-Projects-Template.csv','customer,region,industry,status,positions,headcount,service,salary,salaryUnit,fee,feeUnit,taxRate,updated,notes\r\n');showToast('Không truy cập được file XLSX tích hợp; đã tạo template CSV thay thế.')})}
function rowsToCsv(rows){const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];return [keys.map(csvCell).join(','),...rows.map(r=>keys.map(k=>csvCell(r[k])).join(','))].join('\r\n')}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(quoted){if(c==='"'&&n==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell.length||row.length){row.push(cell);if(row.some(x=>x.trim()))rows.push(row)}if(rows.length<2)throw Error('CSV phải có hàng tiêu đề và ít nhất một hàng dữ liệu.');const headers=rows.shift().map(x=>x.trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??'']))).filter(r=>Object.values(r).some(v=>String(v).trim()))}
function importHeaderKey(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function findImportColumn(headers,aliases){const norm=headers.map(h=>[h,importHeaderKey(h)]);for(const alias of aliases){const a=importHeaderKey(alias);const exact=norm.find(x=>x[1]===a);if(exact)return exact[0]}for(const alias of aliases){const a=importHeaderKey(alias);if(a.length>3){const partial=norm.find(x=>x[1].includes(a)||a.includes(x[1]));if(partial)return partial[0]}}return null}
function parseImportedMoney(value){if(value===null||value===undefined||value==='')return '';if(typeof value==='number')return value;const raw=String(value).trim();const m=raw.match(/[-+]?\d[\d.,\s]*/);if(!m)return '';let n=m[0].replace(/\s/g,'');const comma=n.lastIndexOf(','),dot=n.lastIndexOf('.');if(comma>=0&&dot>=0){const dec=Math.max(comma,dot);const tail=n.length-dec-1;if(tail>0&&tail<=2){const whole=n.slice(0,dec).replace(/[.,]/g,'');n=whole+'.'+n.slice(dec+1)}else n=n.replace(/[.,]/g,'')}else if(comma>=0){const tail=n.length-comma-1;n=tail>0&&tail<=2?n.replace(/\./g,'').replace(',','.'):n.replace(/,/g,'')}else if(dot>=0){const tail=n.length-dot-1;n=tail>0&&tail<=2?n.replace(/,/g,''):n.replace(/[.,]/g,'')}const num=Number(n);return Number.isFinite(num)?num:''}
function importedFeeUnit(value){const t=importHeaderKey(value);if(t.includes('ngay')||t.includes('day'))return 'VNĐ/người/ngày';if(t.includes('gio')||t.includes('hour'))return 'VNĐ/người/giờ';if(t.includes('thang')||t.includes('month'))return 'VNĐ/người/tháng';if(t.includes('%'))return '% lương tháng';return 'Phí cố định/lần'}
function smartImportRows(rows){if(!rows.length)return null;const headers=Object.keys(rows[0]||{});const cols={region:findImportColumn(headers,['Khu vực','Region','Địa bàn','Địa điểm']),industry:findImportColumn(headers,['Lĩnh vực của KH','Lĩnh vực khách hàng','Ngành nghề','Ngành','Industry','Lĩnh vực']),customer:findImportColumn(headers,['Tên Dự án (tên KH)','Tên dự án','Tên khách hàng','Khách hàng','Doanh nghiệp','Customer','Project name']),position:findImportColumn(headers,['Vị trí nhân sự','Vị trí công việc','Vị trí','Chức danh','Position','Job title']),fee:findImportColumn(headers,['Phí Dịch vụ – năm gần nhất','Phí dịch vụ năm gần nhất','Phí dịch vụ','Service fee','Fee','Đơn giá dịch vụ']),year:findImportColumn(headers,['Năm','Năm phí','Year'])};if(!cols.region||!cols.industry||!cols.customer||!cols.position)return null;const projects=[],clients=[],pricing=[];const seenClients=new Set(),seenProjects=new Set(),seenPricing=new Set();for(const row of rows){const val=k=>String(cols[k]?row[cols[k]]??'':'').trim();const region=val('region'),industry=val('industry'),customer=val('customer'),positionRaw=val('position'),feeRaw=val('fee'),year=val('year')||(String(feeRaw).match(/20\d{2}/)||[])[0]||'';if(!customer&&!positionRaw)continue;const positions=[...new Set(positionRaw.split(/\r?\n|\s*;\s*|\s*\|\s*/).map(x=>x.trim()).filter(Boolean))];const projectKey=[customer,region,industry,positions.join('|')].map(importHeaderKey).join('~');if(customer&&!seenProjects.has(projectKey)){seenProjects.add(projectKey);projects.push({id:'',customer,region,industry,status:'Cần xác minh',positions:positions.join('\n'),headcount:'',service:'BPO / cung ứng nhân sự',salary:'',salaryUnit:'Theo tháng (VNĐ/tháng)',fee:parseImportedMoney(feeRaw),feeUnit:importedFeeUnit(feeRaw),taxRate:'',updated:today(),notes:`Nhập tự động từ dữ liệu có sẵn${year?' · dữ liệu phí năm '+year:''}. Cần xác minh trạng thái dự án và đơn vị tính.`})}const clientKey=importHeaderKey(customer);if(customer&&!seenClients.has(clientKey)){seenClients.add(clientKey);clients.push({id:'',name:customer,region,industry,type:'Khách hàng tiềm năng',status:'Cần nghiên cứu',website:'',source:'File dữ liệu do người dùng cung cấp',sourceUrl:'',updated:today(),notes:'Được nhập tự động từ bảng dữ liệu hiện có; cần xác minh quan hệ khách hàng và trạng thái hợp tác.'})}for(const pos of positions){const fee=parseImportedMoney(feeRaw),unit=importedFeeUnit(feeRaw);const key=[pos,region,industry,fee,unit].map(importHeaderKey).join('~');if(seenPricing.has(key))continue;seenPricing.add(key);pricing.push({id:'',position:pos,region,industry,salaryMin:'',salaryMax:'',salaryUnit:'Theo tháng (VNĐ/tháng)',feeMin:fee,feeMax:fee,feeUnit:unit,taxRate:'',model:'Phí dịch vụ lịch sử',service:'BPO / cung ứng nhân sự',source:'File dữ liệu do người dùng cung cấp',sourceUrl:'',verified:'Cần xác minh',updated:today(),notes:`Phí nguồn gốc: ${feeRaw||'không có'}${year?' · năm '+year:''}. Đã tự nhận diện cột; xác minh đơn vị và phạm vi phí trước khi dùng làm benchmark.`})}}if(!projects.length&&!clients.length&&!pricing.length)return null;return {data:{projects,clients,pricing},kind:'smart',sourceRows:rows.length}}
function standardizeImportRows(rows,key){return rows.map(r=>{const out={};for(const [k,v] of Object.entries(r)){const nk=importHeaderKey(k).replace(/\s/g,'');out[k]=v}return out})}
const BACKUP_ENC_FORMAT='BPOHUB_ENCRYPTED_BACKUP';
function bytesToB64(bytes){let bin='';for(let i=0;i<bytes.length;i++)bin+=String.fromCharCode(bytes[i]);return btoa(bin)}
function b64ToBytes(text){const bin=atob(text);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
async function encryptBackupJson(plain,password){if(window.AndroidDownloads&&typeof window.AndroidDownloads.encryptBackup==='function'){const result=window.AndroidDownloads.encryptBackup(plain,password);if(!result||result.startsWith('ERROR:'))throw Error(result?result.slice(6):'Không mã hóa được file trên Android.');return JSON.parse(result)}if(!window.crypto?.subtle)throw Error('Thiết bị/trình duyệt không hỗ trợ mã hóa an toàn. Hãy dùng APK Android mới hoặc trình duyệt HTTPS.');const enc=new TextEncoder(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(plain));return {format:BACKUP_ENC_FORMAT,version:1,algorithm:'AES-256-GCM',kdf:'PBKDF2-SHA256',iterations:210000,salt:bytesToB64(salt),iv:bytesToB64(iv),ciphertext:bytesToB64(new Uint8Array(cipher)),createdAt:new Date().toISOString()}}
async function decryptBackupJson(envelope,password){if(window.AndroidDownloads&&typeof window.AndroidDownloads.decryptBackup==='function'){const result=window.AndroidDownloads.decryptBackup(JSON.stringify(envelope),password);if(!result||result.startsWith('ERROR:'))throw Error(result?result.slice(6):'Không giải mã được file.');return result}if(!window.crypto?.subtle)throw Error('Thiết bị/trình duyệt không hỗ trợ giải mã an toàn. Hãy dùng APK Android mới hoặc trình duyệt HTTPS.');const enc=new TextEncoder(),material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:b64ToBytes(envelope.salt),iterations:Number(envelope.iterations||210000),hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['decrypt']);const clear=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(envelope.iv)},key,b64ToBytes(envelope.ciphertext));return new TextDecoder().decode(clear)}
function isEncryptedBackup(value){return value&&value.format===BACKUP_ENC_FORMAT&&value.salt&&value.iv&&value.ciphertext}
function requestImportBackup(){const input=$('#importFile');if(input){input.value='';input.click()}}
function setupDataPage(){const down=$('#downloadTemplate');if(down)down.onclick=()=>{if(!window.XLSX){downloadBundledTemplate();showToast('Đang chuẩn bị template. Hãy chọn nơi lưu tệp nếu được hỏi.');return}const wb=XLSX.utils.book_new();const sheets={Projects:[['customer','region','industry','status','positions','headcount','service','salary','salaryUnit','fee','feeUnit','taxRate','updated','notes']],Clients:[['name','region','industry','type','status','website','sourceUrl','notes']],SalaryFees:[['position','region','industry','salaryMin','salaryMax','salaryUnit','feeMin','feeMax','feeUnit','taxRate','model','service','source','sourceUrl','verified','updated','notes']],Leads:[['name','region','industry','potential','signal','source','sourceUrl','contact','owner','score','status','updated','notes']]};for(const [n,rows] of Object.entries(sheets))XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),n);downloadXlsx(wb,'BPO-Intelligence-Hub-Excel-Template.xlsx')};const ex=$('#exportExcel');if(ex)ex.onclick=()=>{if(!window.XLSX){downloadText('BPO-Intelligence-Hub-Export-'+today()+'.csv',rowsToCsv([{table:'Projects',records:JSON.stringify(db.projects)},{table:'Clients',records:JSON.stringify(db.clients)},{table:'SalaryFees',records:JSON.stringify(db.pricing)},{table:'Leads',records:JSON.stringify(db.leads)}]));showToast('Đã xuất một tệp CSV chứa dữ liệu sao lưu dạng JSON theo từng bảng.');return}const wb=XLSX.utils.book_new();for(const [name,key] of [['Projects','projects'],['Clients','clients'],['SalaryFees','pricing'],['Leads','leads']]){const rows=db[key].length?db[key]:[{note:'Chưa có dữ liệu'}];XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),name)}downloadXlsx(wb,'BPO-Intelligence-Hub-Export-'+today()+'.xlsx')};const file=$('#excelFile');if(file)file.onchange=async()=>{pendingExcel=null;$('#commitExcel').disabled=true;$('#excelPreview').innerHTML='';const f=file.files[0];if(!f)return;try{let data={},total=0,smart=false,sourceRows=[];if(f.name.toLowerCase().endsWith('.csv')){sourceRows=parseCsv(await f.text());const first=sourceRows[0]||{};const map={Projects:'projects',Clients:'clients',SalaryFees:'pricing',Leads:'leads'};const sheetKey=Object.keys(map).find(k=>Object.keys(first).some(h=>h.toLowerCase()===k.toLowerCase()));if(sheetKey){data[map[sheetKey]]=sourceRows;total=sourceRows.length}else{const mapped=smartImportRows(sourceRows);if(mapped){data=mapped.data;smart=true;total=sourceRows.length}else{const firstKey=Object.keys(first)[0]||'';const target=({'customer':'projects','name':'clients','position':'pricing','potential':'leads'}[firstKey]);if(!target)throw Error('Không nhận diện được cột. Cần có tối thiểu Khu vực, Lĩnh vực của KH, Tên Dự án (tên KH), Vị trí nhân sự; hoặc dùng template của app.');data[target]=sourceRows;total=sourceRows.length}}}else{if(!window.XLSX)throw Error('Không có thư viện đọc .xlsx khi offline. Hãy xuất sheet cần nhập thành CSV UTF-8 hoặc kết nối Internet.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});const map={Projects:'projects',Clients:'clients',SalaryFees:'pricing',Leads:'leads'};for(const [sheet,key] of Object.entries(map)){if(wb.Sheets[sheet]){data[key]=XLSX.utils.sheet_to_json(wb.Sheets[sheet],{defval:''}).filter(r=>Object.values(r).some(v=>String(v).trim()));total+=data[key].length}}if(!total){const candidate=wb.SheetNames.map(name=>({name,rows:XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:''}).filter(r=>Object.values(r).some(v=>String(v).trim()))})).find(x=>x.rows.length);if(candidate){const mapped=smartImportRows(candidate.rows);if(mapped){data=mapped.data;smart=true;total=candidate.rows.length}}}}if(!total)throw Error('Không tìm thấy dòng dữ liệu. Với Excel theo cấu trúc riêng, hãy bảo đảm có tiêu đề cột và tối thiểu Khu vực, Lĩnh vực của KH, Tên Dự án, Vị trí nhân sự.');pendingExcel={data,smart};const counts=Object.entries(data).map(([k,v])=>`${({projects:'Dự án',clients:'Khách hàng',pricing:'Vị trí / phí',leads:'Cơ hội'}[k]||k)}: ${v.length}`).join(' · ');$('#excelPreview').innerHTML=`<div class="callout"><b>Đọc được ${total} dòng nguồn.</b><br>${counts}${smart?'<br><br><b>Đã tự nhận diện cấu trúc file.</b> Mỗi dòng có thể tạo/cập nhật dữ liệu dự án, khách hàng và benchmark vị trí/phí. Các bản ghi mới được đánh dấu “Cần xác minh”; hãy kiểm tra trước khi sử dụng.':'<br>Đã nhận diện cấu trúc template của ứng dụng.'}</div>`;$('#commitExcel').disabled=false}catch(e){$('#excelPreview').innerHTML=`<div class="callout">Không đọc được file: ${esc(e.message||'lỗi không xác định')}. Hãy kiểm tra hàng tiêu đề hoặc xuất sheet sang CSV UTF-8.</div>`}};const commit=$('#commitExcel');if(commit)commit.onclick=()=>{if(!pendingExcel)return;const defs={projects:['P','customer'],clients:['C','name'],pricing:['R','position'],leads:['L','name']};let added=0,skipped=0;for(const [key,rows] of Object.entries(pendingExcel.data)){for(const row of rows){const clean={};for(const [k,v] of Object.entries(row))clean[k]=v;const primary=defs[key][1];const match=pendingExcel.smart&&db[key].find(x=>importHeaderKey(x[primary])===importHeaderKey(clean[primary])&&importHeaderKey(x.region)===importHeaderKey(clean.region)&&(key!=='pricing'||importHeaderKey(x.position)===importHeaderKey(clean.position)));if(match){Object.assign(match,clean,{id:match.id,updated:today()});skipped++;continue}if(!clean.id||db[key].some(x=>String(x.id)===String(clean.id)))clean.id=defs[key][0]+'-IMP-'+String(Date.now()+added).slice(-8);if(!clean.updated)clean.updated=today();db[key].push(clean);added++}}if(!save())return;pendingExcel=null;render();showToast(`Đã thêm ${added} bản ghi${skipped?`; cập nhật ${skipped} bản ghi trùng`:''}.`)};}

function showDetailRecord(title,fields,type,id){const body=$('#detailBody');if(!body||!$('#detailBackdrop')){showToast('Không mở được cửa sổ chi tiết. Hãy tải lại ứng dụng.');return}$('#detailTitle').textContent=title;body.innerHTML=`<div class="detail-grid">${fields.filter(([k,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`<div class="detail-item"><span>${esc(k)}</span><strong>${esc(String(v??'—'))}</strong></div>`).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="detailClose">Đóng</button>${type&&id?`<button class="primary-btn" id="detailEdit" data-edit="${esc(type)}" data-id="${esc(id)}">Sửa thông tin</button>`:''}</div>`;$('#detailBackdrop').classList.remove('hidden');const close=()=>$('#detailBackdrop').classList.add('hidden');$('#detailClose').onclick=close;$('#detailX').onclick=close;$('#detailBackdrop').onclick=e=>{if(e.target===$('#detailBackdrop'))close()};const edit=$('#detailEdit');if(edit)edit.onclick=e=>{e.stopPropagation();close();openForm(type,id)}}
