$('#menuBtn').addEventListener('click',openMenu);$('#mobileNavBackdrop')?.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')navigateBack()});let swipeStart=null;document.addEventListener('touchstart',e=>{if(e.touches.length!==1){swipeStart=null;return}const target=e.target;if(target.closest('input,textarea,select,button,a,[contenteditable="true"],.table-wrap,.finder-table,.modal,[data-no-swipe]')){swipeStart=null;return}const t=e.touches[0];swipeStart={x:t.clientX,y:t.clientY,edge:t.clientX<28};},{passive:true});document.addEventListener('touchend',e=>{if(!swipeStart||!e.changedTouches.length)return;const t=e.changedTouches[0],dx=t.clientX-swipeStart.x,dy=t.clientY-swipeStart.y,edge=swipeStart.edge;swipeStart=null;if(dx>105&&Math.abs(dy)<55&&edge&&t.clientX>100){navigateBack()}},{passive:true});document.addEventListener('click',async e=>{const target=e.target.closest('#saveBackupJsonBtn,#saveEncryptedBackupBtn,#loadBackupBtn');if(!target)return;if(target.id==='saveBackupJsonBtn'){const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString(),app:'BPO Intelligence Hub',schemaVersion:1},null,2)],{type:'application/json;charset=utf-8'});downloadBlob('bpo-intelligence-backup-'+today()+'.json',blob);showToast('Đang lưu bản sao lưu JSON. Chọn nơi lưu tệp nếu được hỏi.');return}if(target.id==='loadBackupBtn'){requestImportBackup();return}if(target.id==='saveEncryptedBackupBtn'){const password=prompt('Đặt mật khẩu cho file sao lưu mã hóa (tối thiểu 8 ký tự):');if(password===null)return;if(password.length<8){showToast('Mật khẩu cần tối thiểu 8 ký tự.');return}const confirmPassword=prompt('Nhập lại mật khẩu để xác nhận:');if(confirmPassword!==password){showToast('Mật khẩu xác nhận không khớp.');return}try{const payload=JSON.stringify({...db,exportedAt:new Date().toISOString(),app:'BPO Intelligence Hub',schemaVersion:1},null,2);const envelope=await encryptBackupJson(payload,password);downloadBlob('bpo-intelligence-backup-'+today()+'.bpoenc',new Blob([JSON.stringify(envelope)],{type:'application/octet-stream'}));showToast('Đã tạo file sao lưu mã hóa. Hãy lưu lại mật khẩu ở nơi an toàn.')}catch(err){showToast('Không mã hóa được file: '+(err.message||'lỗi không xác định'))}}});$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{let d=JSON.parse(await file.text());if(isEncryptedBackup(d)){const password=prompt('File sao lưu đã mã hóa. Nhập mật khẩu để giải mã:');if(password===null){showToast('Đã hủy giải mã.');return}const clear=await decryptBackupJson(d,password);d=JSON.parse(clear)}if(!['projects','clients','pricing','leads'].every(k=>Array.isArray(d[k])))throw Error('File không có cấu trúc sao lưu hợp lệ.');if(confirm('Khôi phục sẽ thay thế dữ liệu hiện tại trên thiết bị. Bạn đã xuất bản sao lưu dữ liệu hiện tại chưa?')){db={projects:d.projects,clients:d.clients,pricing:d.pricing,leads:d.leads};if(!save())return;render();showToast('Đã giải mã và khôi phục bản sao lưu thành công.')}}catch(err){showToast('Không mở được file: '+(err.message||'file sai định dạng hoặc mật khẩu không đúng.'))}finally{e.target.value=''}});

