if(window.matchMedia){const systemThemeMedia=window.matchMedia('(prefers-color-scheme: dark)');const refreshSystemTheme=()=>{try{const settings=JSON.parse(localStorage.getItem('bpo-ui-settings')||'{}');if(settings.theme==='auto')applySettings()}catch{}};if(systemThemeMedia.addEventListener)systemThemeMedia.addEventListener('change',refreshSystemTheme);else if(systemThemeMedia.addListener)systemThemeMedia.addListener(refreshSystemTheme)}applySettings();render();refreshMarketSignals();
